from langflow.custom import Component
from langflow.io import SecretStrInput, StrInput, MessageTextInput, Output
from langflow.schema import Message
import requests


class ResearchAgentAPITool(Component):
    display_name = "Research Agent API Tool"
    description = "Memanggil Web Research Assistant secara langsung melalui Langflow API."
    icon = "search"

    inputs = [
        MessageTextInput(
            name="question",
            display_name="Question",
            info="Pertanyaan yang dikirim ke Research Agent.",
            tool_mode=True,
        ),
        SecretStrInput(
            name="api_key",
            display_name="Langflow API Key",
            info="API key Langflow.",
            required=True,
        ),
        StrInput(
            name="flow_id",
            display_name="Research Flow ID",
            info="Flow ID Web Research Assistant.",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="result",
            display_name="Research Result",
            method="run_research",
            types=["Message"],
        ),
    ]

    def run_research(self) -> Message:
        api_key = (
            self.api_key.get_secret_value()
            if hasattr(self.api_key, "get_secret_value")
            else str(self.api_key)
        )

        flow_id = str(self.flow_id).strip()
        question = (self.question or "").strip()

        if not api_key:
            raise ValueError("Langflow API Key belum diisi.")

        if not flow_id:
            raise ValueError("Research Flow ID belum diisi.")

        if not question:
            raise ValueError("Question tidak boleh kosong.")

        url = (
            f"http://127.0.0.1:7860/api/v1/run/"
            f"{flow_id}?stream=false"
        )

        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
            "x-api-key": api_key,
        }

        payload = {
            "input_value": question,
            "input_type": "chat",
            "output_type": "chat",
        }

        response = requests.post(
            url,
            headers=headers,
            json=payload,
            timeout=120,
        )

        if response.status_code != 200:
            raise ValueError(
                f"Research Agent API gagal.\n"
                f"Status: {response.status_code}\n"
                f"Response: {response.text}"
            )

        data = response.json()

        try:
            text = (
                data["outputs"][0]
                ["outputs"][0]
                ["results"]["message"]["data"]["text"]
            )
        except (KeyError, IndexError, TypeError) as exc:
            raise ValueError(
                f"Struktur response tidak dikenali:\n{data}"
            ) from exc

        return Message(text=text)

